function table_ready(PDO $pdo):void{static $r=false;if($r)return;$pdo->exec("CREATE TABLE IF NOT EXISTS organizational_committee(id INT UNSIGNED NOT NULL AUTO_INCREMENT,name_bn VARCHAR(150) NOT NULL DEFAULT '',name_en VARCHAR(150) NOT NULL DEFAULT '',designation_bn VARCHAR(150) NOT NULL DEFAULT '',designation_en VARCHAR(150) NOT NULL DEFAULT '',image_url VARCHAR(500) DEFAULT NULL,status TINYINT(1) NOT NULL DEFAULT 1,sort_order INT NOT NULL DEFAULT 0,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY idx_committee_status_sort(status,sort_order,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");$r=true;}
