if($_SERVER['REQUEST_METHOD']!=='POST')cj(['error'=>'Invalid request'],405);admin_only();$in=json_decode(file_get_contents('php://input'),true)?:[];if(!Security::validateCSRF((string)($in['csrf_token']??'')))cj(['error'=>'CSRF token mismatch'],419);
if($action==='save'){$id=(int)($in['id']??0);$v=[trim((string)($in['name_bn']??'')),trim((string)($in['name_en']??'')),trim((string)($in['designation_bn']??'')),trim((string)($in['designation_en']??'')),trim((string)($in['image_url']??'')),!empty($in['status'])?1:0,(int)($in['sort_order']??0)];if($v[0]===''&&$v[1]==='')cj(['error'=>'Member name is required'],422);if($id){$s=$pdo->prepare('UPDATE organizational_committee SET name_bn=?,name_en=?,designation_bn=?,designation_en=?,image_url=?,status=?,sort_order=? WHERE id=?');$s->execute([...$v,$id]);}else{$s=$pdo->prepare('INSERT INTO organizational_committee(name_bn,name_en,designation_bn,designation_en,image_url,status,sort_order) VALUES(?,?,?,?,?,?,?)');$s->execute($v);$id=(int)$pdo->lastInsertId();}cj(['status'=>'success','id'=>$id]);}
if($action==='delete'){$id=(int)($in['id']??0);if($id<=0)cj(['error'=>'Invalid member'],422);$s=$pdo->prepare('SELECT image_url FROM organizational_committee WHERE id=?');$s->execute([$id]);$row=$s->fetch();$pdo->prepare('DELETE FROM organizational_committee WHERE id=?')->execute([$id]);if($row&&!empty($row['image_url'])&&str_starts_with($row['image_url'],'assets/uploads/committee/')){$p=__DIR__.'/'.$row['image_url'];if(is_file($p))@unlink($p);}cj(['status'=>'success']);}
